INSERT INTO item VALUES (1,'Acid Warding','Armor','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy',NULL,NULL,'\n      <div topic=\"Acid Warding\" level=\"8\"><p><b>Acid Warding:</b> The armor absorbs the first 50 points of acid damage per round that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price:</i> +6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (2,'Cold Warding','Armor','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy',NULL,NULL,'\n      <div topic=\"Cold Warding\" level=\"8\"><p><b>Cold Warding:</b> The armor absorbs the first 50 points of cold damage per round that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price:</i> +6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (3,'Exceptional Arrow Deflection','Shield','Epic','Yes',NULL,'23','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, shield, wall of force',NULL,NULL,'\n      <div topic=\"Exceptional Arrow Deflection\" level=\"8\"><p><b>Exceptional Arrow Deflection:</b> This shield functions like a <i>shield of arrow deflection</i> except that it can deflect any type of ranged attack (including spells that require a ranged touch attack) as if it were an arrow. Any time the bearer would normally be struck by a ranged attack, he or she can make a Reflex saving throw (DC 20). If the ranged attack has an enhancement bonus (or a spell level), the DC increases by that amount. If he or she succeeds, the shield deflects the attack. The bearer must be aware of the attack and not flat-footed. Attempting to deflect a ranged attack doesn\'t count as an action.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>shield</i>,  <i>wall of force; Market Price: +</i>8 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (4,'Fire Warding','Armor','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy',NULL,NULL,'\n      <div topic=\"Fire Warding\" level=\"8\"><p><b>Fire Warding:</b> The armor absorbs the first 50 points of fire damage per round that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (5,'Great Invulnerability (10/magic)','Armor, Shield','Epic','Yes',NULL,'19','+4 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, stoneskin, wish, or miracle',NULL,NULL,'\n      <div topic=\"Great Invulnerability\" level=\"8\"><p><b>Great Invulnerability:</b> This suit of armor or shield grants the wearer damage reduction. The damage reduction can be 10/magic, 15/magic, 5/epic, or 10/epic, depending on the armor.</p><p><i>Caster Level:</i> 19th (10/magic), 20th (15/magic), 21st (5/epic), 22nd (10/epic); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>stoneskin</i>,  <i>wish</i>,  or <i>miracle; Market Price:+</i>4 bonus (10/magic), +5 bonus (15/magic), +6 bonus (5/epic), +7 bonus (10/epic).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (6,'Great Invulnerability (15/magic)','Armor, Shield','Epic','Yes',NULL,'19','+5 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, stoneskin, wish, or miracle',NULL,NULL,'\n      <div topic=\"Great Invulnerability\" level=\"8\"><p><b>Great Invulnerability:</b> This suit of armor or shield grants the wearer damage reduction. The damage reduction can be 10/magic, 15/magic, 5/epic, or 10/epic, depending on the armor.</p><p><i>Caster Level:</i> 19th (10/magic), 20th (15/magic), 21st (5/epic), 22nd (10/epic); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>stoneskin</i>,  <i>wish</i>,  or <i>miracle; Market Price:+</i>4 bonus (10/magic), +5 bonus (15/magic), +6 bonus (5/epic), +7 bonus (10/epic).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (7,'Great Invulnerability (5/epic)','Armor, Shield','Epic','Yes',NULL,'19','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, stoneskin, wish, or miracle',NULL,NULL,'\n      <div topic=\"Great Invulnerability\" level=\"8\"><p><b>Great Invulnerability:</b> This suit of armor or shield grants the wearer damage reduction. The damage reduction can be 10/magic, 15/magic, 5/epic, or 10/epic, depending on the armor.</p><p><i>Caster Level:</i> 19th (10/magic), 20th (15/magic), 21st (5/epic), 22nd (10/epic); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>stoneskin</i>,  <i>wish</i>,  or <i>miracle; Market Price:+</i>4 bonus (10/magic), +5 bonus (15/magic), +6 bonus (5/epic), +7 bonus (10/epic).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (8,'Great Invulnerability (10/epic)','Armor, Shield','Epic','Yes',NULL,'19','+7 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, stoneskin, wish, or miracle',NULL,NULL,'\n      <div topic=\"Great Invulnerability\" level=\"8\"><p><b>Great Invulnerability:</b> This suit of armor or shield grants the wearer damage reduction. The damage reduction can be 10/magic, 15/magic, 5/epic, or 10/epic, depending on the armor.</p><p><i>Caster Level:</i> 19th (10/magic), 20th (15/magic), 21st (5/epic), 22nd (10/epic); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>stoneskin</i>,  <i>wish</i>,  or <i>miracle; Market Price:+</i>4 bonus (10/magic), +5 bonus (15/magic), +6 bonus (5/epic), +7 bonus (10/epic).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (9,'Great Reflection','Shield','Epic','Yes',NULL,'25','+10 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, spell turning',NULL,NULL,'\n      <div topic=\"Great Reflection\" level=\"8\"><p><b>Great Reflection:</b> Any time its bearer of this shield is targeted with a spell, it automatically reflects the spell back at the caster (as the <i>spell turning</i> spell). The wearer can lower or raise this effect as a free action (thus allowing beneficial spells in as desired).</p><p><i>Caster Level:</i> 25th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>spell turning; Market Price: +</i>10 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (10,'Great Spell Resistance (21)','Armor, Shield','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Great Spell Resistance\" level=\"8\"><p><b>Great Spell Resistance:</b> This suit of armor or shield grants the wearer spell resistance. The spell resistance can be 21, 23, 25, or 27, depending on the armor.</p><p><i>Caster Level:</i> 21st (SR 21), 22nd (SR 23), 23rd (SR 25), 24th (SR 27); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>spell resistance; Market Price: +</i>6 bonus (SR 21), +7 bonus (SR 23), +8 bonus (SR 25), +9 bonus (SR 27).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (11,'Great Spell Resistance (23)','Armor, Shield','Epic','Yes',NULL,'21','+7 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Great Spell Resistance\" level=\"8\"><p><b>Great Spell Resistance:</b> This suit of armor or shield grants the wearer spell resistance. The spell resistance can be 21, 23, 25, or 27, depending on the armor.</p><p><i>Caster Level:</i> 21st (SR 21), 22nd (SR 23), 23rd (SR 25), 24th (SR 27); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>spell resistance; Market Price: +</i>6 bonus (SR 21), +7 bonus (SR 23), +8 bonus (SR 25), +9 bonus (SR 27).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (12,'Great Spell Resistance (25)','Armor, Shield','Epic','Yes',NULL,'21','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Great Spell Resistance\" level=\"8\"><p><b>Great Spell Resistance:</b> This suit of armor or shield grants the wearer spell resistance. The spell resistance can be 21, 23, 25, or 27, depending on the armor.</p><p><i>Caster Level:</i> 21st (SR 21), 22nd (SR 23), 23rd (SR 25), 24th (SR 27); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>spell resistance; Market Price: +</i>6 bonus (SR 21), +7 bonus (SR 23), +8 bonus (SR 25), +9 bonus (SR 27).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (13,'Great Spell Resistance (27)','Armor, Shield','Epic','Yes',NULL,'21','+9 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, spell resistance',NULL,NULL,'\n      <div topic=\"Great Spell Resistance\" level=\"8\"><p><b>Great Spell Resistance:</b> This suit of armor or shield grants the wearer spell resistance. The spell resistance can be 21, 23, 25, or 27, depending on the armor.</p><p><i>Caster Level:</i> 21st (SR 21), 22nd (SR 23), 23rd (SR 25), 24th (SR 27); <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>spell resistance; Market Price: +</i>6 bonus (SR 21), +7 bonus (SR 23), +8 bonus (SR 25), +9 bonus (SR 27).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (14,'Infinite Arrow Deflection','Shield','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from arrows, shield',NULL,NULL,'\n      <div topic=\"Infinite Arrow Deflection\" level=\"8\"><p><b>Infinite Arrow Deflection:</b> This shield functions like a <i>shield of arrow deflection</i>, though it can deflect any number of projectiles or thrown weapons each round. Any time the bearer would normally be struck by a ranged weapon, he or she can make a Reflex saving throw (DC 20). If the ranged weapon has an enhancement bonus, the DC increases by that amount. If he or she succeeds, the shield deflects the weapon. The bearer must be aware of the attack and not flat-footed. Attempting to deflect a ranged weapon doesn\'t count as an action. Exceptional ranged weapons, such as boulders hurled by giants or ranged spells,  can\'t be deflected.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from arrows</i>,  <i>shield; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (15,'Lightning Warding','Armor','Epic','Yes',NULL,'21','+6 bonus',NULL,'Prereq-uisites: Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy',NULL,NULL,'\n      <div topic=\"Lightning Warding\" level=\"8\"><p><b>Lightning Warding:</b> The armor absorbs the first 50 points of lightning damage per round that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p><i>Caster Level:</i> 21st; <i>Prereq-uisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (16,'Negating','Armor','Epic','Yes',NULL,'20','+5 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, greater dispel magic',NULL,NULL,'\n      <div topic=\"Negating\" level=\"8\"><p><b>Negating:</b> Immediately after the wearer of this armor is hit with a magic weapon, the armor casts <i>greater dispel magic</i> on the weapon. (In the case of projectile weapons, the armor casts <i>greater dispel magic</i> on the weapon that fired the projectile if it is in range. If it is out of range, the armor does nothing.) No weapon can be affected by the armor more than once per day (regardless of the success of the dispel check).</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>greater dispel magic; Market Price: +</i>5 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (17,'Sonic Warding','Armor','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy',NULL,NULL,'\n      <div topic=\"Sonic Warding\" level=\"8\"><p><b>Sonic Warding:</b> The armor absorbs the first 50 points of sonic damage per round that the wearer would normally take (similar to the <i>resist energy</i> spell).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price: +</i>6 bonus.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (18,'Antimagic Armor','Armor','Epic','No',NULL,'21','871,500 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, greater dispel magic, stoneskin, wish or miracle','436,500 gp + 18,700 XP',NULL,'\n      <div topic=\"Antimagic Armor\" level=\"8\"><p><b>Antimagic Armor:</b> This +<i>1 negating full plate armor of invulnerability</i> is crafted of adamantine (and thus has damage reduction 3/-). The armor provides a -5 penalty on dispel checks made against it or its wearer.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>greater dispel magic</i>,  <i>stoneskin</i>,  <i>wish</i> or <i>miracle; Market Price:</i> 871,500 gp; <i>Cost to Create:</i> 436,500 gp + 18,700 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (19,'Armor of the Abyssal Horde','Armor','Epic','No',NULL,'20','768,260 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, creator must be evil, energy drain','385,260 gp + 17,660 XP',NULL,'\n      <div topic=\"Armor of the Abyssal Horde\" level=\"8\"><p><b>Armor of the Abyssal Horde:</b> This+<i>6 full plate armor\'s</i> clawed gauntlets are effectively +4 keen weapons (1d10/19-20) that afflict the target as if she had been struck by an <i>energy drain</i> spell (Fortitude negates DC 23). The armor bestows two negative levels on any nonevil creature wearing it. These negative levels persist as long as the armor is worn and disappear when the armor is removed. The negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the armor is worn.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, creator must be evil, <i>energy drain; Market Price:</i> 768,260 gp; <i>Cost to Create:</i> 385,260 gp + 17,660 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (20,'Armor of the Celestial Battalion','Armor','Epic','No',NULL,'20','616,300 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, creator must be good, magic circle against evil','308,300 gp + 16,160 XP',NULL,'\n      <div topic=\"Armor of the Celestial Battalion\" level=\"8\"><p><b>Armor of the Celestial Battalion:</b> This+<i>7 chainmail</i> is so fine and light that it can be worn under normal clothing without revealing its presence. It has a maximum Dexterity bonus of +10, no armor check penalty, and an arcane spell failure chance of 10%. It is considered light armor, and it allows the wearer to fly at will (as the <i>fly</i> spell). Furthermore, the wearer is at all times surrounded by a <i>magic circle against evil</i> effect (as the spell) which, if dispelled, can be created again as a free action.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, creator must be good, <i>magic circle against evil; Market Price:</i> 616,300 gp; <i>Cost to Create:</i> 308,300 gp + 16,160 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (21,'Bulwark of the Great Dragon','Shield','Epic','No',NULL,'20','1,612,970 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy','806,570 gp + 26,128 XP',NULL,'\n      <div topic=\"Bulwark of the Great Dragon\" level=\"8\"><p><b>Bulwark of the Great Dragon:</b> This +<i>6 heavy shield</i> bears the image of a dragon\'s head. Three times per day, the bearer of the shield can command it to belch forth a breath weapon of the appropriate type. The range of this breath weapon is 80 feet (if a line) or 40 feet (if a cone). Regardless of the type, the breath weapon deals 20d6 points of damage. In addition, the shield provides the bearer with resistance 50 to the energy type that matches its breath weapon. To determine what type of <i>dragon shield</i> is found, roll d% and consult the following table:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>d%</b><br/></td>\n<td><b>Color</b><br/></td>\n<td><b>Breath</b> <br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>01-10<br/></td>\n<td>Black<br/></td>\n<td>Line of acid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>11-20<br/></td>\n<td>Blue<br/></td>\n<td>Line of lightning<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>21-30<br/></td>\n<td>Brass<br/></td>\n<td>Line of fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>31-40<br/></td>\n<td>Bronze<br/></td>\n<td>Line of lightning<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>41-50<br/></td>\n<td>Copper<br/></td>\n<td>Line of acid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>51-60<br/></td>\n<td>Gold<br/></td>\n<td>Cone of fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>61-70<br/></td>\n<td>Green<br/></td>\n<td>Cone of corrosive (acid) gas<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>71-80<br/></td>\n<td>Red<br/></td>\n<td>Cone of fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>81-90<br/></td>\n<td>Silver<br/></td>\n<td>Cone of cold<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>91-100<br/></td>\n<td>White<br/></td>\n<td>Cone of cold<br/></td>\n\n</tr>\n</table><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy; Market Price:</i> 1,612,970 gp; <i>Cost to Create:</i> 806,570 gp + 26,128 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (22,'Dragonskin Armor','Armor','Epic','No',NULL,'24','564,550 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from energy, shapechange','283,250 gp + 15,629 XP',NULL,'\n      <div topic=\"Dragonskin Armor\" level=\"8\"><p><b>Dragonskin Armor:</b> This+<i>5 full plate armor</i> is crafted from the hide of a great wyrm dragon. At the wearer\'s command, the armor sprouts enormous dragon wings, allowing the wearer to fly at a speed of 90 feet (clumsy) for a total of 4 hours each day. The armor also grants immunity to a specific type of energy, based on the color of dragon that supplied the armor. Roll d% on the following table to determine the color and immunity.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>d%</b><br/></td>\n<td><b>Color</b><br/></td>\n<td><b>Immunity</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>01-10<br/></td>\n<td>Black<br/></td>\n<td>Acid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>11-20<br/></td>\n<td>Blue<br/></td>\n<td>Lightning<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>21-30<br/></td>\n<td>Brass<br/></td>\n<td>Fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>31-40<br/></td>\n<td>Bronze<br/></td>\n<td>Lightning<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>41-50<br/></td>\n<td>Copper<br/></td>\n<td>Acid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>51-60<br/></td>\n<td>Gold<br/></td>\n<td>Fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>61-70<br/></td>\n<td>Green<br/></td>\n<td>Acid<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>71-80<br/></td>\n<td>Red<br/></td>\n<td>Fire<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>81-90<br/></td>\n<td>Silver<br/></td>\n<td>Cold<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>91-100<br/></td>\n<td>White<br/></td>\n<td>Cold<br/></td>\n\n</tr>\n</table><p>The wearer of the armor takes a -4 circumstance penalty on Diplomacy checks with dragons, but gains a +4 circumstance bonus on Intimidate checks against dragons.</p><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from energy</i>,  <i>shapechange; Market Price:</i> 564,550 gp; <i>Cost to Create:</i> 283,250 gp + 15,629 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (23,'Shapeshifter\'s Armor','Armor','Epic','No',NULL,'21','400,165 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, shapechange or wild shape ability','200,165 gp + 14,000 XP',NULL,'\n      <div topic=\"Shapeshifter\'s Armor\" level=\"8\"><p><b>Shapeshifter\'s Armor:</b> This suit of +<i>6 hide armor</i> grants its full Armor Class bonus regardless of any form the wearer takes (with <i>polymorph</i>,  <i>shapechange</i>,  <i>wild shape</i>,  or similar abilities).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>shapechange</i> or <i>wild shape</i> ability; <i>Market Price:</i> 400,165 gp; <i>Cost to Create:</i> 200,165 gp + 14,000 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (24,'Warlord\'s Breastplate','Armor','Epic','No',NULL,'21','416,200 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, charm monster, sympathy','210,200 gp + 14,120 XP',NULL,'\n      <div topic=\"Warlord\'s Breastplate\" level=\"8\"><p><b>Warlord\'s Breastplate:</b> This +<i>6 mithral breastplate</i> has an armor check penalty of -1, a maximum Dexterity bonus of +5, and an arcane spell failure chance of 15%. It is considered light armor and weighs 15 pounds. It grants the wearer a +4 enhancement bonus to Charisma and allows the wearer to attract and lead a number of followers as if he or she had the Leadership feat (though this power doesn\'t allow the wearer to attract a cohort). If the wearer already has the Leadership feat, this armor has no cumulative effect on his or her followers.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>charm monster</i>,  <i>sympathy; Market Price:</i> 416,200 gp; <i>Cost to Create:</i> 210,200 gp + 14,120 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (25,'Acidic Blast','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, acid fog',NULL,NULL,'\n      <div topic=\"Acidic Blast\" level=\"8\"><p><b>Acidic Blast:</b> On command, an acidic blast weapon drips acid (though this deals no damage to the wielder). On any hit, this acid splashes the creature struck, dealing +3d6 points of bonus acid damage. On a successful critical hit it instead deals +6d6 points of acid damage (or +9d6 if the critical multiplier is x3, or +12d6 if the critical multiplier is x4). Bows, crossbows, and slings with this special ability bestow the bonus acid damage upon their ammunition.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>acid fog; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (26,'Anarchic Power','Weapon','Epic','Yes',NULL,'21','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, word of chaos',NULL,NULL,'\n      <div topic=\"Anarchic Power\" level=\"8\"><p><b>Anarchic Power:</b> This weapon is chaos-aligned and thus bypasses the corresponding damage reduction. When a weapon of anarchic power strikes a lawful target, this power deals +3d6 points of bonus chaotic damage to the target, and the target gains one negative level (Fortitude DC 23 to remove 24 hours later). On a successful critical hit it instead deals +6d6 points of chaotic damage and bestows two negative levels (or +9d6 and three negative levels if the critical multiplier is x3, or +12d6 and four negative levels if the critical multiplier is x4). The weapon bestows three negative levels on any lawful creature attempting to wield it. These negative levels remain as long as the weapon is in hand and disappear when the weapon is no longer wielded. These negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings with this special ability bestow the anarchic power upon their ammunition. This special ability does not stack with the nonepic anarchic special ability. </p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>word of chaos; Market Price: +</i>8 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (27,'Axiomatic Power','Weapon','Epic','Yes',NULL,'23','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, dictum',NULL,NULL,'\n      <div topic=\"Axiomatic Power\" level=\"8\"><p><b>Axiomatic Power:</b> This weapon is lawful-aligned and thus bypasses the corresponding damager reduction. When a weapon of axiomatic power strikes a chaotic target, this power erupts forth and deals +3d6 points of bonus lawful damage to the target, and the target gains one negative level (Fortitude DC 23 to remove 24 hours later). On a successful critical hit it instead deals +6d6 points of lawful damage and bestows two negative levels (or +9d6 and three negative levels if the critical multiplier is x3, or +12d6 and four negative levels if the critical multiplier is x4). The weapon bestows three negative levels on any chaotic creature attempting to wield it. These negative levels remain as long as the weapon is in hand and disappear when the weapon is no longer wielded. These negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings with this special ability bestow the lawful power upon their ammunition. This special ability does not stack with the nonepic axiomatic special ability.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>dictum; Market Price: +</i>8 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (28,'Distant Shot','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, discern location',NULL,NULL,'\n      <div topic=\"Distant Shot\" level=\"8\"><p><b>Distant Shot:</b> A distant shot weapon can be used against any target within line of sight at no penalty for range.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>discern location; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (29,'Dread','Weapon','Epic','Yes',NULL,'22','+7 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, summon monster IX',NULL,NULL,'\n      <div topic=\"Dread\" level=\"8\"><p><b>Dread:</b> A dread weapon excels at attacking one type of creature. Against its designated foe, its effective enhancement bonus is +4 better than its normal enhancement bonus. Further, it deals +4d6 points of bonus damage against the foe, and if it scores a successful critical hit against the foe, that creature must make a Fortitude save (DC 27) or be destroyed instantly and turned to dust. (This even affects creatures immune to critical hits or death magic.) To randomly determine a dread weapon\'s designated foe, roll on the following table.</p><p><i>Caster Level:</i> 22nd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>summon monster IX; Market Price: +</i>7 bonus.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>d%</b><br/></td>\n<td><b>Designated Foe</b><br/></td>\n<td><b>d%</b><br/></td>\n<td><b>Designated Foe</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>01-05<br/></td>\n<td>Aberrations<br/></td>\n<td>58-60<br/></td>\n<td>Humanoids, orc<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>06-09<br/></td>\n<td>Animals<br/></td>\n<td>61-65<br/></td>\n<td>Magical beasts<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>10-16<br/></td>\n<td>Constructs<br/></td>\n<td>66-70<br/></td>\n<td>Monstrous humanoids<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>17-22<br/></td>\n<td>Dragons<br/></td>\n<td>71-72<br/></td>\n<td>Oozes<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>23-27<br/></td>\n<td>Elementals<br/></td>\n<td>73<br/></td>\n<td>Outsiders, air<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>28-32<br/></td>\n<td>Fey<br/></td>\n<td>74-76<br/></td>\n<td>Outsiders, chaotic<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>33-39<br/></td>\n<td>Giants<br/></td>\n<td>77<br/></td>\n<td>Outsiders, earth<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>40<br/></td>\n<td>Humanoids, aquatic<br/></td>\n<td>78-80<br/></td>\n<td>Outsiders, evil<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>41-42<br/></td>\n<td>Humanoids, dwarf<br/></td>\n<td>81<br/></td>\n<td>Outsiders, fire<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>43-44<br/></td>\n<td>Humanoids, elf<br/></td>\n<td>82-84<br/></td>\n<td>Outsiders, good<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>45<br/></td>\n<td>Humanoids, gnoll<br/></td>\n<td>85-87<br/></td>\n<td>Outsiders, lawful<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>46<br/></td>\n<td>Humanoids, gnome<br/></td>\n<td>88<br/></td>\n<td>Outsiders, water<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>47-49<br/></td>\n<td>Humanoids, goblinoid<br/></td>\n<td>89-90<br/></td>\n<td>Plants<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>50<br/></td>\n<td>Humanoids, halfling<br/></td>\n<td>91-98<br/></td>\n<td>Undead<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>51-54<br/></td>\n<td>Humanoids, human<br/></td>\n<td>99-100<br/></td>\n<td>Vermin<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>55-57<br/></td>\n<td>Humanoids, reptilian<br/></td>\n<td/>\n<td/>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (30,'Everdancing','Weapon','Epic','Yes',NULL,'23','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, animate objects',NULL,NULL,'\n      <div topic=\"Everdancing\" level=\"8\"><p><b>Everdancing:</b> An everdancing weapon is much like a dancing weapon, though it can be loosed with a free action and will fight as long as desired. It can move up to 60 feet away from its owner. Its owner can instruct it to move to a different target as a move-equivalent action. If its owner is rendered unconscious or otherwise unable to direct it, it will fight the same opponent as long as that opponent is conscious and within range. The owner of an everdancing weapon can grasp it again as a free action (assuming it is within reach).</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>animate objects; Market Price: +</i>8 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (31,'Fiery Blast','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, fireball',NULL,NULL,'\n      <div topic=\"Fiery Blast\" level=\"8\"><p><b>Fiery Blast:</b> On command, a fiery blast weapon is sheathed in fire (though this deals no damage to the wielder). On any hit, this fire engulfs the creature struck, dealing +3d6 points of bonus fire damage. On a successful critical hit it instead deals +6d6 points of fire damage (or +9d6 if the critical multiplier is x3, or +12d6 if the critical multiplier is x4). Bows, crossbows, and slings with this special ability bestow the bonus fire damage upon their ammunition.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>fireball; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (32,'Holy Power','Weapon','Epic','Yes',NULL,'23','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, holy word',NULL,NULL,'\n      <div topic=\"Holy Power\" level=\"8\"><p><b>Holy Power:</b> This weapon is good-aligned and thus bypasses the corresponding damager reduction. When a weapon of holy power strikes an evil target, this power erupts forth and deals +3d6 points of bonus holy (good) damage to the target, and the target gains one negative level (Fortitude DC 23 to remove 24 hours later). On a successful critical hit it instead deals +6d6 points of holy (good) damage and bestows two negative levels (or +9d6 and three negative levels if the critical multiplier is x3, or +12d6 and four negative levels if the critical multiplier is x4). The weapon bestows three negative levels on any evil creature attempting to wield it. These negative levels remain as long as the weapon is in hand and disappear when the weapon is no longer wielded. These negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings with this special ability bestow the holy power upon their ammunition. This special ability does not stack with the nonepic holy special ability.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>holy word; Market Price: +</i>8 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (33,'Icy Blast','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, cone of cold',NULL,NULL,'\n      <div topic=\"Icy Blast\" level=\"8\"><p><b>Icy Blast:</b> On command, an icy blast weapon is sheathed in icy cold (though this deals no damage to the wielder). On any hit, this cold washes over the creature struck, dealing+3d6 points of bonus cold damage. On a successful critical hit it instead deals +6d6 points of cold damage (or +9d6 if the critical multiplier is x3, or +12d6 if the critical multiplier is x4). Bows, crossbows, and slings with this special ability bestow the bonus cold damage upon their ammunition.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>cone of cold; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (34,'Lightning Blast','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, lightning bolt',NULL,NULL,'\n      <div topic=\"Lightning Blast\" level=\"8\"><p><b>Lightning Blast:</b> On command, a lightning blast weapon crackles with electrical energy (though this deals no damage to the wielder). On any hit, lightning coruscates around the creature struck, dealing +3d6 points of bonus electricity damage. On a successful critical hit it instead deals +6d6 points of electricity damage (or +9d6 if the critical multiplier is x3, or +12d6 if the critical multiplier is x4). Bows, crossbows, and slings with this special ability bestow the bonus electricity damage upon their ammunition.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>lightning bolt; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (35,'Mighty Disruption','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, true resurrection',NULL,NULL,'\n      <div topic=\"Mighty Disruption\" level=\"8\"><p><b>Mighty Disruption:</b> Any undead creature struck in combat must succeed at a Fortitude save (DC 21) or be destroyed. A weapon of mighty disruption must be a bludgeoning weapon. (If this property is rolled for a piercing or slashing weapon, reroll.)</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>true resurrection; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (36,'Sonic Blast','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, shout',NULL,NULL,'\n      <div topic=\"Sonic Blast\" level=\"8\"><p><b>Sonic Blast:</b> On command, a sonic blast weapon emits a low thrumming hum (though this deals no damage to the wielder). On any hit, this becomes a thunderous roar that deals +3d6 points of bonus sonic damage to the creature struck. On a successful critical hit it instead deals +6d6 points of sonic damage (or +9d6 if the critical multiplier is x3, or +12d6 if the critical multiplier is x4). Bows, crossbows, and slings with this special ability bestow the bonus sonic damage upon their ammunition.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>shout; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (37,'Triple-Throw','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, shades',NULL,NULL,'\n      <div topic=\"Triple-Throw\" level=\"8\"><p><b>Triple-Throw:</b> This special ability can only be placed on a weapon that can be thrown. (If this property is rolled for a weapon that cannot be thrown, reroll.) A triple-throw weapon creates two duplicates of itself when thrown. Both the original and the duplicate weapons attack separately (at the same attack bonus). Regardless of the success of any of the attacks, the duplicates immediately disappear after the attack is completed. Any bonuses on damage due to accuracy or precision (including those from sneak attacks, the Precise Shot feat, or the ranger\'s favored enemy bonus) apply only to the original weapon\'s damage, not to the duplicates.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>shades; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (38,'Unerring Accuracy','Weapon','Epic','Yes',NULL,'21','+6 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, true seeing',NULL,NULL,'\n      <div topic=\"Unerring Accuracy\" level=\"8\"><p><b>Unerring Accuracy:</b> Ranged attacks made with this weapon negate the AC bonus granted by any cover short of total cover.  The weapon\'s ranged attacks also ignore any miss chance from concealment (including total concealment, but the must still aim his or her attacks at the correct square).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>true seeing; Market Price: +</i>6 bonus.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (39,'Unholy Power','Weapon','Epic','Yes',NULL,'23','+8 bonus',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, unholy word',NULL,NULL,'\n      <div topic=\"Unholy Power\" level=\"8\"><p><b>Unholy Power:</b> This weapon is evil-aligned and this bypasses the corresponding damage reduction. When a weapon of unholy power strikes a good target, this power erupts forth and deals +3d6 points of bonus unholy (evil) damage to the target, and the target gains one negative level (Fortitude DC 23 to remove 24 hours later). On a successful critical hit it instead deals +6d6 points of unholy (evil) damage and bestows two negative levels (or +9d6 and three negative levels if the critical multiplier is x3, or +12d6 and four negative levels if the critical multiplier is x4). The weapon bestows three negative levels on any good creature attempting to wield it. These negative levels remain as long as the weapon is in hand and disappear when the weapon is no longer wielded. These negative levels never result in actual level loss, but they cannot be overcome in any way (including <i>restoration</i> spells) while the weapon is wielded. Bows, crossbows, and slings with this special ability bestow the unholy power upon their ammunition. This special ability does not stack with the nonepic unholy special ability.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>unholy word; Market Price: +</i>8 bonus.</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (40,'Backstabber','Weapon','Epic','No',NULL,'21','770,310 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, inflict moderate wounds','385,310 gp + 17,700 XP',NULL,'\n      <div topic=\"Backstabber\" level=\"8\"><p><b>Backstabber:</b> This +<i>6 short sword</i> adds +2d6 to the wielder\'s sneak attack damage. If the wielder does not have the sneak attack ability, this weapon does not grant it.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>inflict moderate</i> <i>wounds; Market Price:</i> 770,310 gp; <i>Cost to Create:</i> 385,310 gp + 17,700 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (41,'Chaosbringer','Weapon','Epic','No',NULL,'23','4,025,350 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, rage, mass charm monster','2,012,850 gp + 50,250 XP',NULL,'\n      <div topic=\"Chaosbringer\" level=\"8\"><p><b>Chaosbringer:</b> This +<i>6 greataxe of anarchic power</i> grants its wielder the ability to fly into a rage (identical to a barbarian\'s rage) once per day (or one additional time per day if the wielder already has the rage class feature). If the wielder has the greater rage class feature, the weapon also grants the wielder the Incite Rage epic feat.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>rage</i>,  <i>mass charm monster; Market Price:</i> 4,025,350 gp; <i>Cost to Create:</i> 2,012,850 gp + 50,250 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (42,'Elven Greatbow','Weapon','Epic','No',NULL,'23','2,900,400 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, bull\'s strength, keen edge, true seeing','1,450,400 gp + 39,400 XP',NULL,'\n      <div topic=\"Elven Greatbow\" level=\"8\"><p><b>Elven Greatbow:</b> In the hands of any nonelf, this bow performs only as a +<i>2 composite longbow</i>. In the hands of an elf, this weapon functions as a +<i>5 composite longbow of unerring accuracy</i> with a Strength bonus that matches its elven wielder\'s current Strength at all times. Furthermore, any arrows loosed from the bow are considered keen, regardless of the enhancement bonus of the arrow fired.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>bull\'s strength</i>,  <i>keen edge</i>,  <i>true seeing; Market Price:</i> 2,900,400 gp; <i>Cost to Create:</i> 1,450,400 gp + 39,400 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (43,'Everwhirling Chain','Weapon','Epic','No',NULL,'23','5,220,325 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, animate objects, haste, shield (or shield of faith)','2,610,325 gp + 52,200 XP',NULL,'\n      <div topic=\"Everwhirling Chain\" level=\"8\"><p><b>Everwhirling Chain:</b> This +<i>4 defending everdancing spiked chain of speed</i> continuously twitches in its wielder\'s hands. The wielder of the <i>everwhirling chain</i> can use it to make any number of attacks of opportunity per round (as if he or she had the Improved Combat Reflexes feat).</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>animate objects</i>,  <i>haste</i>,  <i>shield</i> (or <i>shield of faith</i>); <i>Market Price:</i> 5,220,325 gp; <i>Cost to Create:</i> 2,610,325 gp + 52,200 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (44,'Finaldeath','Weapon','Epic','No',NULL,'22','3,580,308 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, death ward, plane shift, summon monster IX, creator must be able to turn undead','1,790,308 gp + 45,800 XP',NULL,'\n      <div topic=\"Finaldeath\" level=\"8\"><p><b>Finaldeath:</b> This +<i>5 undead dread ghost touch morningstar</i> also grants its wielder immunity to energy drain attacks. Furthermore, if its wielder is capable of turning undead, he or she gains the Positive Energy Aura feat.</p><p><i>Caster Level:</i> 22nd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>death ward</i>,  <i>plane shift</i>,  <i>summon monster IX</i>,  creator must be able to turn undead; <i>Market Price:</i> 3,580,308 gp; <i>Cost to Create:</i> 1,790,308 gp + 45,800 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (45,'Gripsoul','Weapon','Epic','No',NULL,'27','1,856,500 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, binding','934,500 gp + 28,440 XP',NULL,'\n      <div topic=\"Gripsoul\" level=\"8\"><p><b>Gripsoul:</b> <i>Gripsoul</i> is a +<i>6 keen long-sword</i>,  but instead of dealing additional damage on a critical hit, the weapon imprisons the victim in a gem set in the pommel of the sword as per a <i>binding</i> spell heightened to 16th level (DC 30). The same is true of any blow that would otherwise kill a foe or knock him or her unconscious. Only one creature can be so held, but the wielder can release the bound soul at any time with a command word.</p><p><i>Caster Level:</i> 27th; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>binding; Market Price:</i> 1,856,500 gp; <i>Cost to Create:</i> 934,500 gp + 28,440 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (46,'Holy Devastator','Weapon','Epic','No',NULL,'23','4,620,315 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, holy aura, holy smite, holy word','2,310,315 gp + 56,200 XP',NULL,'\n      <div topic=\"Holy Devastator\" level=\"8\"><p><b>Holy Devastator:</b> In the hands of any character other than a paladin, this sword performs as a +<i>3 holy longsword</i>. In the hands of a paladin, this weapon functions as a +<i>7 longsword of holy power</i> and grants a +5 sacred bonus on the wielder\'s saving throws against spells with the evil descriptor or spells cast by evil characters. If the paladin wielder smites evil with the <i>holy devastator</i>,  he or she adds twice his or her paladin level to damage (rather than his or her paladin level).</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>holy aura</i>,  <i>holy smite</i>,  <i>holy word; Market Price:</i> 4,620,315 gp; <i>Cost to Create:</i> 2,310,315 gp + 56,200 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (47,'Mace of Ruin','Weapon','Epic','No',NULL,'21','1,000,312 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, disintegrate','500,312 gp + 20,000 XP',NULL,'\n      <div topic=\"Mace of Ruin\" level=\"8\"><p><b>Mace of Ruin:</b> This +<i>7 heavy mace</i> ignores the hardness or damage reduction of any object or creature it strikes. Furthermore, the weapon can deal critical hits to objects and constructs as if they were living creatures.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>disintegrate; Market Price:</i> 1,000,312 gp; <i>Cost to Create:</i> 500,312 gp + 20,000 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (48,'Quarterstaff of Alacrity','Weapon','Epic','No',NULL,'21','462,600 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, protection from arrows, shield','231,600 gp + 14,620 XP',NULL,'\n      <div topic=\"Quarterstaff of Alacrity\" level=\"8\"><p><b>Quarterstaff of Alacrity:</b> Both ends of this +<i>5 quarterstaff of speed</i> have equal enhancement and special powers, meaning that it allows an additional attack with each end every round. While the <i>Quarterstaff of alacrity</i> is held, it grants its wielder a +5 resistance bonus on Reflex saves. It also deflects ranged weapons as if the wielder had the Deflect Arrows and Infinite Deflection feats.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>protection from arrows</i>,  <i>shield; Market Price:</i> 462,600 gp; <i>Cost to Create:</i> 231,600 gp + 14,620 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (49,'Souldrinker','Weapon','Epic','No',NULL,'21','478,335 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Spell Focus (Necromancy), energy drain','239,315 gp + 14,780 XP',NULL,'\n      <div topic=\"Souldrinker\" level=\"8\"><p><b>Souldrinker:</b> This +<i>5 bastard sword</i> bestows 2d4 negative levels on its target whenever it deals damage, just as if its target had been struck by the <i>energy drain</i> spell. Each negative level bestowed grants the wielder 5 temporary hit points. One day after being struck, the subject must make a Fortitude save (DC 25) for each negative level or lose a level. If this sword\'s power causes a character to have negative levels at least equal to his or her current level, the character is instantly slain and the wielder gains an additional 10 temporary hit points. Temporary hit points gained from this weapon last for a maximum of 1 hour.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Spell Focus (Necromancy), <i>energy drain; Market Price:</i> 478,335 gp; <i>Cost to Create:</i> 239,315 gp + 14,780 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (50,'Stormbrand','Weapon','Epic','No',NULL,'21','235,350 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, blindness/deafness, call lightning or lightning bolt, control winds, fly, protection from energy','117,850 gp + 12,350 XP',NULL,'\n      <div topic=\"Stormbrand\" level=\"8\"><p><b>Stormbrand:</b> This +<i>4 thundering shocking burst greatsword</i> allows its wielder to fly at will (as the <i>fly</i> spell). Furthermore, the wielder can move normally (including flying) even in the strongest winds. When the weapon is drawn, the wielder gains electricity resistance 30 and sonic resistance 30.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>blindness/deafness</i>,  <i>call lightning</i> or <i>lightning bolt</i>,  <i>control winds</i>,  <i>fly</i>,  <i>protection from energy; Market Price:</i> 235,350 gp; <i>Cost to Create:</i> 117,850 gp + 12,350 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (51,'Unholy Despoiler','Weapon','Epic','No',NULL,'23','4,650,315 gp',NULL,'Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, blasphemy, unholy aura, unholy blight','2,325,315 gp + 56,500 XP',NULL,'\n      <div topic=\"Unholy Despoiler\" level=\"8\"><p><b>Unholy Despoiler:</b> In the hands of any character other than a blackguard, this sword performs as a +<i>3 unholy longsword</i>. In the hands of a blackguard, this weapon functions as a +<i>7 longsword of unholy power</i> and grants a +5 profane bonus on the wielder\'s saving throws against spells with the good descriptor or spells cast by good characters. If a blackguard wielder smites good with the <i>unholy despoiler</i>, he or she adds twice his or her blackguard level to damage (rather than his or her blackguard level).</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>blasphemy</i>,  <i>unholy aura</i>,  <i>unholy blight; Market Price:</i> 4,650,315 gp; <i>Cost to Create:</i> 2,325,315 gp + 56,500 XP.</p><p/><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (52,'Universal Energy Resistance, Minor','Ring',NULL,'No',NULL,'15','84,000 gp',NULL,'Forge Ring, protection from energy',NULL,NULL,'\n      <div topic=\"Universal Energy Resistance, Minor\" level=\"8\"><p><b>Universal Energy Resistance, Minor:</b> This ring functions as a <i>ring of minor energy resistance</i> for all types of energy: fire, cold, electricity, acid, and sonic. When the wearer would normally take such damage, subtract 10 points of damage per round from the amount before applying. This is a nonepic magic item.</p><p><i>Caster Level:</i> 15th; <i>Prerequisites:</i> Forge Ring, <i>protection from energy; Market Price:</i> 84,000 gp.</p><p/><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (53,'Adamant Law','Ring','Epic','No',NULL,'15','250,000 gp',NULL,'Forge Ring, Forge Epic Ring, shield of law, creator must be lawful',NULL,NULL,'\n      <div topic=\"Adamant Law\" level=\"8\"><p><b>Adamant Law:</b>  The wearer of this ring is constantly sheathed in a <i>shield of law</i> effect. It bestows one negative level on any chaotic creature that puts it on. The negative level remains as long as the ring is worn and disappears when the ring is removed. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the ring is worn.</p><p><i>Caster Level:</i> 15th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>shield of law</i>,  creator must be lawful; <i>Market Price:</i> 250,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (54,'Chaotic Fury','Ring','Epic','No',NULL,'15','250,000 gp',NULL,'Forge Ring, Forge Epic Ring, cloak of chaos, creator must be chaotic',NULL,NULL,'\n      <div topic=\"Chaotic Fury\" level=\"8\"><p><b>Chaotic Fury:</b> The wearer of this ring is constantly sheathed in a <i>cloak of chaos</i> effect. It bestows one negative level on any lawful creature that puts it on. The negative level remains as long as the ring is worn and disappears when the ring is removed. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the ring is worn.</p><p><i>Caster Level:</i> 15th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>cloak of chaos</i>,  creator must be chaotic; <i>Market Price:</i> 250,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (55,'Energy Immunity','Ring','Epic','No',NULL,'20','240,000 gp. Epic',NULL,'Forge Ring, Forge Epic Ring, protection from energy',NULL,NULL,'\n      <div topic=\"Energy Immunity\" level=\"8\"><p><b>Energy Immunity:</b> This band continually provides the wearer with immunity to a single type of energy: fire, cold, electricity, acid, or sonic. The wearer takes no damage from the energy of the specific type.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>protection from energy; Market Price:</i> 240,000 gp. Epic</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (56,'Protection +6','Ring','Epic','No',NULL,'20','720,000 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus to Armor Class of +6 or higher.</p><p><i>Caster Level:</i> 20th: <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>shield of faith</i>,  creator\'s caster level must be three times the ring\'s bonus; <i>Market Price:</i> 720,000 gp (+6), 980,000 gp (+7), 1,280,000 gp (+8), 1,620,000 gp (+9), 2,000,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (57,'Protection +7','Ring','Epic','No',NULL,'20','980,000 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus to Armor Class of +6 or higher.</p><p><i>Caster Level:</i> 20th: <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>shield of faith</i>,  creator\'s caster level must be three times the ring\'s bonus; <i>Market Price:</i> 720,000 gp (+6), 980,000 gp (+7), 1,280,000 gp (+8), 1,620,000 gp (+9), 2,000,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
