INSERT INTO item VALUES (65,'Epic Wizardry IX','Ring','Epic','No',NULL,'23','810,000 gp',NULL,'Forge Ring, Forge Epic Ring, wish',NULL,NULL,'\n      <div topic=\"Epic Wizardry\" level=\"8\"><p><b>Epic Wizardry:</b> Like the <i>ring of wizardry</i>,  this ring comes in a variety of types useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one particular spell level. An <i>epic ring of wizardry V</i> doubles 5th-level spells, an <i>epic ring of wizardry VI</i> doubles 6th-level spells, an <i>epic ring of wizardry VII</i> doubles 7th-level spells, an <i>epic ring of wizardry VIII</i> doubles 8th-level spells, and an <i>epic ring of wizardry IX</i> doubles 9th-level spells. Bonus spells from high ability scores, school specialization, or any other source are not doubled.</p><p><i>Caster Level:</i> 23rd (<i>epic wizardry</i> V), 26th (<i>epic wizardry VI</i>), 29th (<i>epic wizardry VII</i>), 32nd (<i>epic wizardry VIII</i>), 35th (<i>epic wizardry IX</i>); <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>wish; Market Price:</i> 250,000 gp (<i>epic wizardry</i> V), 360,000 gp (<i>epic wizardry VI</i>), 490,000 gp (<i>epic wizardry VII</i>), 640,000 gp (<i>epic wizardry VIII</i>), 810,000 gp (<i>epic wizardry IX</i>).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (66,'Ineffable Evil','Ring','Epic','No',NULL,'15','250,000 gp',NULL,'Forge Ring, Forge Epic Ring, unholy aura, creator must be evil',NULL,NULL,'\n      <div topic=\"Ineffable Evil\" level=\"8\"><p><b>Ineffable Evil:</b> The wearer of this ring is constantly sheathed in an <i>unholy aura</i> effect. It bestows one negative level on any good creature that puts it on. The negative level remains as long as the ring is worn and disappears when the ring is removed. This negative level never results in actual level loss, but it cannot be overcome in any way (including <i>restoration</i> spells) while the ring is worn.</p><p><i>Caster Level:</i> 15th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>unholy aura</i>,  creator must be evil; <i>Market Price:</i> 250,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (67,'Ironskin','Ring','Epic','No',NULL,'20','400,000 gp',NULL,'Forge Ring, Forge Epic Ring, iron body',NULL,NULL,'\n      <div topic=\"Ironskin\" level=\"8\"><p><b>Ironskin:</b> This ring grants its wearer damage reduction 15/adamantine.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>iron body; Market Price:</i> 400,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (68,'Rapid Healing','Ring','Epic','No',NULL,'20','300,000 gp',NULL,'Forge Ring, Forge Epic Ring, regenerate',NULL,NULL,'\n      <div topic=\"Rapid Healing\" level=\"8\"><p><b>Rapid Healing:</b> This ring grants a living wearer fast healing 3. It must be worn for 24 hours before its powers activate, and if removed it will not function again until it has been worn for 24 hours by the same individual.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>regenerate; Market Price:</i> 300,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (69,'Sequestering','Ring','Epic','No',NULL,'20','300,000 gp',NULL,'Forge Ring, Forge Epic Ring, sequester',NULL,NULL,'\n      <div topic=\"Sequestering\" level=\"8\"><p><b>Sequestering:</b> This ring becomes invisible when worn. Upon command, the wearer gains the benefits of a <i>sequester</i> spell (though he or she does not become comatose as normal for the spell).</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>sequester; Market Price:</i> 300,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (70,'Universal Energy Immunity','Ring','Epic','No',NULL,'20','2,160,000 gp',NULL,'Forge Ring, Forge Epic Ring, protection from energy',NULL,NULL,'\n      <div topic=\"Universal Energy Immunity\" level=\"8\"><p><b>Universal Energy Immunity:</b> This ring functions as a <i>ring of energy immunity</i> for all types of energy- fire, cold, electricity, acid, and sonic. The wearer takes no damage from energy of any of these types.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>protection from energy; Market Price:</i> 2,160,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (71,'Universal Energy Resistance, Greater','Ring','Epic','No',NULL,'20','308,000 gp',NULL,'Forge Ring, Forge Epic Ring, protection from energy','154,000 gp + 13,080 XP',NULL,'\n      <div topic=\"Universal Energy Resistance, Greater\" level=\"8\"><p><b>Universal Energy Resistance, Greater:</b> This ring functions as a <i>ring of greater energy resistance</i> for all types of energy-fire, cold, electricity, acid, and sonic. When the wearer would normally take such damage, subtract 30 points of damage per round from the amount before applying.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>protection from energy; Market Price:</i> 308,000 gp; <i>Cost to Create:</i> 154,000 gp + 13,080 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (72,'Virtuous Good','Ring','Epic','No',NULL,'15','250,000 gp',NULL,'Forge Ring, Forge Epic Ring, holy aura, creator must be good','125,000 gp + 12,500 XP',NULL,'\n      <div topic=\"Virtuous Good\" level=\"8\"><p><b>Virtuous Good:</b> The wearer of this ring is constantly sheathed in a <i>holy aura</i> effect. It bestows one negative level on any evil creature that puts it on. The negative level remains as long as the ring is worn and disappears when the ring is removed. This negative level never results in actual level loss, but it cannot be over-come in any way (including <i>restoration</i> spells) while the ring is worn.</p><p><i>Caster Level:</i> 15th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>holy aura</i>,  creator must be good; <i>Market Price:</i> 250,000 gp; <i>Cost to Create:</i> 125,000 gp + 12,500 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (73,'Weaponbreaking','Ring','Epic','No',NULL,'20','600,000 gp',NULL,'Forge Ring, Forge Epic Ring, iron body, shatter','300,000 gp + 16,000 XP',NULL,'\n      <div topic=\"Weaponbreaking\" level=\"8\"><p><b>Weaponbreaking:</b> A <i>ring of weaponbreaking</i> is identical to a <i>ring of ironskin</i>,  and has one additional power. Any weapon that successfully strikes the wearer must also make a Fortitude saving throw (DC 20) or be shattered into pieces.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>iron body</i>,  <i>shatter; Market Price:</i> 600,000 gp; <i>Cost to Create:</i> 300,000 gp + 16,000 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (74,'Epic Psionics V','Ring','Epic, Psionic','No',NULL,NULL,'250,000 gp','23','Craft Universal Item, Craft Epic Universal Item, great emulation',NULL,NULL,'\n      <div topic=\"Epic Psionics\" level=\"8\"><p><b>Epic Psionics:</b> This special crystal ring comes in a variety of types useful only to psionic characters (characters who have power points per day). The wearer\'s total power points per day are increased, depending on the ring. The points granted are not bonus points-while the ring is worn, it actually increases the wearer\'s points per day, but a night\'s rest is required before gaining access to the increased power point per day total. (Power points are not actually stored in the ring, as would be the case for a crystal capacitor. Instead, the ring grants power points by magnifying the manifester\'s own power.)</p><p>A <i>ring of epic psionics V</i> increases the wearer\'s daily power points by 43 points, a <i>ring of epic psionics VI</i> grants 63 power points, a <i>ring of epic psionics VII</i> grants 87 power points, a <i>ring of epic psionics VIII</i> grants 115 points, and a <i>ring of epic psionics IX</i> grants 147 power points.</p><p><i>Manifester Level:</i> 23rd (<i>epic psionics</i> V), 26th (<i>epic psionics VI</i>), 29th (<i>epic psionics VII</i>), 32nd (<i>epic psionics VIII</i>), 35th (<i>epic psionics IX</i>); <i>Prerequisites:</i> Craft Universal Item, Craft Epic Universal Item, <i>great emulation; Market Price:</i> 250,000 gp (<i>epic psionics</i> V), 360,000 gp (<i>epic psionics VI</i>), 490,000 gp (<i>epic psionics VII</i>), 640,000 gp (<i>epic psionics VIII</i>), 810,000 gp (<i>epic psionics IX</i>).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
