INSERT INTO item VALUES (77,'Epic Psionics VIII','Ring','Epic, Psionic','No',NULL,NULL,'640,000 gp','23','Craft Universal Item, Craft Epic Universal Item, great emulation',NULL,NULL,'\n      <div topic=\"Epic Psionics\" level=\"8\"><p><b>Epic Psionics:</b> This special crystal ring comes in a variety of types useful only to psionic characters (characters who have power points per day). The wearer\'s total power points per day are increased, depending on the ring. The points granted are not bonus points-while the ring is worn, it actually increases the wearer\'s points per day, but a night\'s rest is required before gaining access to the increased power point per day total. (Power points are not actually stored in the ring, as would be the case for a crystal capacitor. Instead, the ring grants power points by magnifying the manifester\'s own power.)</p><p>A <i>ring of epic psionics V</i> increases the wearer\'s daily power points by 43 points, a <i>ring of epic psionics VI</i> grants 63 power points, a <i>ring of epic psionics VII</i> grants 87 power points, a <i>ring of epic psionics VIII</i> grants 115 points, and a <i>ring of epic psionics IX</i> grants 147 power points.</p><p><i>Manifester Level:</i> 23rd (<i>epic psionics</i> V), 26th (<i>epic psionics VI</i>), 29th (<i>epic psionics VII</i>), 32nd (<i>epic psionics VIII</i>), 35th (<i>epic psionics IX</i>); <i>Prerequisites:</i> Craft Universal Item, Craft Epic Universal Item, <i>great emulation; Market Price:</i> 250,000 gp (<i>epic psionics</i> V), 360,000 gp (<i>epic psionics VI</i>), 490,000 gp (<i>epic psionics VII</i>), 640,000 gp (<i>epic psionics VIII</i>), 810,000 gp (<i>epic psionics IX</i>).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (78,'Epic Psionics IX','Ring','Epic, Psionic','No',NULL,NULL,'810,000 gp','23','Craft Universal Item, Craft Epic Universal Item, great emulation',NULL,NULL,'\n      <div topic=\"Epic Psionics\" level=\"8\"><p><b>Epic Psionics:</b> This special crystal ring comes in a variety of types useful only to psionic characters (characters who have power points per day). The wearer\'s total power points per day are increased, depending on the ring. The points granted are not bonus points-while the ring is worn, it actually increases the wearer\'s points per day, but a night\'s rest is required before gaining access to the increased power point per day total. (Power points are not actually stored in the ring, as would be the case for a crystal capacitor. Instead, the ring grants power points by magnifying the manifester\'s own power.)</p><p>A <i>ring of epic psionics V</i> increases the wearer\'s daily power points by 43 points, a <i>ring of epic psionics VI</i> grants 63 power points, a <i>ring of epic psionics VII</i> grants 87 power points, a <i>ring of epic psionics VIII</i> grants 115 points, and a <i>ring of epic psionics IX</i> grants 147 power points.</p><p><i>Manifester Level:</i> 23rd (<i>epic psionics</i> V), 26th (<i>epic psionics VI</i>), 29th (<i>epic psionics VII</i>), 32nd (<i>epic psionics VIII</i>), 35th (<i>epic psionics IX</i>); <i>Prerequisites:</i> Craft Universal Item, Craft Epic Universal Item, <i>great emulation; Market Price:</i> 250,000 gp (<i>epic psionics</i> V), 360,000 gp (<i>epic psionics VI</i>), 490,000 gp (<i>epic psionics VII</i>), 640,000 gp (<i>epic psionics VIII</i>), 810,000 gp (<i>epic psionics IX</i>).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (79,'Besiegement','Rod','Epic','No',NULL,'24','447,745 gp',NULL,'Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, clenched fist, passwall, telepathic bond, transmute rock to mud','224,025 gp + 14,474 XP',NULL,'\n      <div topic=\"Besiegement\" level=\"8\"><p><b>Besiegement:</b>  This rod functions as a +<i>3 light mace</i>. In addition, it is useful for besieging fortifications. Whenever the wielder makes a charge attack, the rod improves to a +6 weapon. Twice per day, the rod can create a battering ram that lasts for 24 rounds. This ram can strike once per round, dealing 20 points of damage with each hit. It cannot be used to target individuals, only fortifications. It can be damaged by normal means (65 hp, AC 22), and <i>disintegrate</i> or <i>dispel magic</i> destroys it. The rod also has the following powers: <i>Siege Engine:</i> One heavy catapult, two light catapults, or three siege towers may be generated with each use of this power. Each weapon created lasts for 12 hours.  The power can be used three times per day. Ammunition for 20 shots is included with each weapon created.</p><p><i>Transmute Rock to Mud:</i> This power can be used three times per day (caster level 24th, save DC 17).</p><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, <i>clenched fist</i>,  <i>passwall</i>,   <i>telepathic bond</i>,  <i>transmute rock to mud; Market Price:</i> 447,745 gp; <i>Cost to Create:</i> 224,025 gp + 14,474 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (80,'Epic Absorption','Rod','Epic','No',NULL,'23','1,500,000 gp',NULL,'Craft Rod, Craft Epic Rod, Empower Spell, Maximize Spell, empowered maximized spell turning',NULL,NULL,'\n      <div topic=\"Epic Absorption\" level=\"8\"><p><b>Epic Absorption:</b> Like a <i>rod of absorption</i>,  this rod draws single-target or ray spells and spell-like abilities into itself, nullifying the effect and storing the potential spell levels until the wielder releases the energy in the form of spells of his or her own. Spells of any level (including those boosted beyond 9th level by metamagic) can be absorbed, although epic spells cannot. The rod absorbs a maximum of 150 spell levels and can thereafter only discharge any remaining potential it might have. The rod cannot be recharged.</p><p><i>Caster Level:</i> 23rd; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Empower Spell, Maximize Spell, empowered maximized <i>spell turning; Market Price:</i> 1,500,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (81,'Epic Cancellation','Rod','Epic','No',NULL,'25','330,000 gp',NULL,'Craft Rod, Craft Epic Rod, dispel magic',NULL,NULL,'\n      <div topic=\"Epic Cancellation\" level=\"8\"><p><b>Epic Cancellation:</b> This rod\'s touch drains an item of all magical properties, including the magical energy in epic magic items (but not most artifacts). The item touched gets a Will saving throw (DC 26). If a creature is holding the magic item at the time, then the item can use the holder\'s Will save bonus in place of its own. In such cases, contact is established by making a melee touch attack roll. Upon draining three items, the rod becomes brittle and useless. Drained items can only be restored by <i>wish</i>,  <i>miracle</i>,  or epic spells specifically designed to restore lost power. A <i>rod of epic cancellation</i> can neutralize a normal <i>sphere of annihilation</i> without itself being cancelled.</p><p><i>Caster Level:</i> 25th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>dispel magic; Market Price:</i> 330,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (82,'Epic Might','Rod','Epic','No',NULL,'30','4,293,432 gp',NULL,'Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, cure critical wounds, inflict critical wounds, bull\'s strength, fireball, dominate person, power word stun','2,151,372 gp + 52,841 XP',NULL,'\n      <div topic=\"Epic Might\" level=\"8\"><p><b>Epic Might:</b> This rod is similar to a <i>rod of lordly might</i>,  although it is far more powerful. It is larger than its normal counterpart, and it is constructed of adamantine rather than normal metal. It has six buttons, several spell-like functions, and several mundane uses, and it can also be used as a magic weapon of various sorts.</p><p>The following spell-like functions of the rod can each be used once per day.</p><ul>\n <li> <i>Dominate Person:</i> Touched foe is recipient of a <i>dominate person</i> spell, if the wielder so commands (Will save DC 24). The wielder must choose to use this power and then succeed with a melee touch attack to activate the power. If the attack fails, the effect is lost.</li>\n <li> <i>Stun:</i> Upon command, all enemies viewing the rod are stunned, as per the <i>power word</i>,  <i>stun</i> spell (10-foot maximum range, Will save DC 24). Invoking this power is a standard action.</li>\n <li> <i>Damage:</i> Upon command, the rod deals 10d8 points of damage to an opponent on a successful touch attack and cures the wielder of a like amount of damage (Will save DC 26). The wielder must choose to use this power before attacking, as with <i>dominate person</i>.</li>\n</ul><p>The following weapon uses of the rod have no limits on their use.</p><ul>\n <li> In its normal form, the rod can be used as a +<i>6 heavy mace</i>. </li>\n <li> When button 1 is pushed, the rod becomes a +<i>3 longsword of fiery blasting</i>. </li>\n <li> When button 2 is pushed, the rod becomes a +<i>8 battleaxe</i>. </li>\n <li> When button 3 is pushed, the rod becomes a +<i>10 shortspear</i> or +<i>10 longspear</i>.</li>\n</ul><p>The following mundane uses of the rod also have no limits on their use.</p><ul>\n <li> Climbing pole/ladder: When button 4 is pushed, a spike that can anchor in granite is extruded from the ball, while the other end sprouts three sharp hooks. The rod lengthens to anywhere between 5 and 150 feet in a single round, stopping when button 4 is pushed again. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, in staggered progression. The rod is firmly held by the spike and hooks and can bear up to 10,000 pounds. The wielder can retract the pole by pushing button 5.</li>\n <li> The ladder function can be used to force open doors. The wielder plants the rod\'s base 30 feet or less from the portal to be forced and in line with it, then pushes button 4. The force exerted has a Strength bonus of+24.</li>\n <li> When button 6 is pushed, the rod indicates magnetic north and gives the wielder a knowledge of his or her approximate depth beneath the surface or height above it.</li>\n</ul><p><i>Caster Level:</i> 30th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, <i>cure critical wounds</i>,  <i>inflict critical wounds</i>,  <i>bull\'s strength</i>,  <i>fireball</i>,  <i>dominate person</i>,  <i>power word stun; Market Price:</i> 4,293,432 gp; <i>Cost to Create:</i> 2,151,372 gp + 52,841 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (83,'Epic Negation','Rod','Epic','No',NULL,'24','446,000 gp',NULL,'Craft Rod, Craft Epic Rod, dispel magic, limited wish or miracle',NULL,NULL,'\n      <div topic=\"Epic Negation\" level=\"8\"><p><b>Epic Negation:</b> This rod negates the spell or spell-like function or functions of magic items, including epic magic items (but not artifacts). The wielder points the rod at the magic item, and a beam shoots forth to touch the target device, attacking as a ray (a ranged touch attack). The ray negates any currently active item function and has a 75% chance to negate any other spell or spell-like functions of that device, regardless of the level or power of the functions, for 2d4 rounds. To negate instantaneous effects, the rod wielder needs to have readied an action. The target item gets no saving throw or means to resist this effect. The rod can function three times per day.</p><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>dispel magic</i>,  <i>limited wish</i> or <i>miracle; Market Price:</i> 446,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (84,'Epic Rulership','Rod','Epic','No',NULL,'25','575,000 gp',NULL,'Craft Rod, Craft Epic Rod, Improved Heighten Spell, improved heightened mass charm','300,000 gp + 15,500 XP',NULL,'\n      <div topic=\"Epic Rulership\" level=\"8\"><p><b>Epic Rulership:</b> This rod appears to be a royal scepter worth at least 25,000 gp in materials and work-manship alone. The wielder can command the obedience and fealty of creatures within 360 feet when he or she activates the device (a standard action). Creatures totaling 900 Hit Dice can be ruled, but creatures with Intelligence scores of 17 or higher are entitled to a Will saving throw (DC 29) to negate the effect. Ruled creatures obey the wielder as if he or she were their absolute sovereign. Still, if the wielder gives a command that is contrary to the nature of the creatures commanded, the magic is broken. The rod can be used for 1,500 total minutes before crumbling to dust. This duration need not be continuous.</p><p><i>Caster Level:</i> 25th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Improved Heighten Spell, improved heightened <i>mass charm; Market Price:</i> 575,000 gp; <i>Cost to Create:</i> 300,000 gp + 15,500 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (85,'Epic Spellcaster','Rod','Epic','No',NULL,'21','245,400 gp',NULL,'Craft Rod, Craft Epic Rod',NULL,NULL,'\n      <div topic=\"Epic Spellcaster\" level=\"8\"><p><b>Epic Spellcaster:</b> This magnificent adamantine rod grants its wielder a +10 insight bonus on Spellcraft checks made to cast epic spells for as long as he or she holds or carries the rod.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod; <i>Market Price:</i> 245,400 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (86,'Epic Splendor','Rod','Epic','No',NULL,'21','297,400 gp',NULL,'Craft Rod, Craft Epic Rod, fabricate, mage\'s magnificent mansion','191,200 gp + 12,124 XP',NULL,'\n      <div topic=\"Epic Splendor\" level=\"8\"><p><b>Epic Splendor:</b> This rod grants its wielder a +8 enhancement bonus to Charisma for as long as he or she holds or carries the item. Three times per day, the rod creates and garbs him or her in clothing of the finest fabrics, plus adornments of fur and jewels. Apparel created by the rod can remain in existence up to 24 hours. The value of the garb ranges from 70,000 to 100,000 gp (1d4+6 x10,000 gp)-10,000 gp for the fabric, 50,000 gp for the furs, and the rest for jewel trim (maximum of 40 gems, maximum value 1,000 gp each). In addition, the rod can, once per week, create a palatial mansion in any floor plan the user desires. The mansion is palatial, able to accommodate up to 250 people, housing them in private chambers and serving them fine banquets. The mansion lasts for three days, after which time it, and everything originally in it (including items removed from the mansion), disappear.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>fabricate</i>,  <i>mage\'s magnificent mansion; Market Price:</i> 297,400 gp; <i>Cost to Create:</i> 191,200 gp + 12,124 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (87,'Excellent Magic','Rod','Epic','No',NULL,'21','650,000 gp',NULL,'Craft Rod, Craft Epic Rod','325,000 gp + 26,000 XP',NULL,'\n      <div topic=\"Excellent Magic\" level=\"8\"><p><b>Excellent Magic:</b> Once per day when casting a nonepic or epic spell that has an experience point component, the rod supplies up to 2,000 XP, not the caster. If more experience points are required to cast the spell, the caster provides them. As a special use of the rod, the caster can substitute the power inherent in the rod for the experience point development cost of an epic spell. Doing so drains all the power from the rod, rendering it useless.</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod; <i>Market Price:</i> 650,000 gp; <i>Cost to Create:</i> 325,000 gp + 26,000 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (88,'Fortification','Rod','Epic','No',NULL,'24','465,665 gp',NULL,'Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, inter-posing hand, create food and water, major creation, wall of iron, wall of stone','231,985 gp + 14,634 XP',NULL,'\n      <div topic=\"Fortification\" level=\"8\"><p><b>Fortification:</b> This rod functions as a +<i>3 light mace</i>. In addition, it is useful for the construction and defense of fortifications. Whenever the wielder is benefiting from cover, the rod improves that to nine-tenths cover (+10 cover AC bonus and +4 cover Reflex save bonus; failure on the save results in half damage and success results in no damage). Three times per day, the rod can create food and water, as per the cleric spell, for twenty-four people. The rod also has the following powers: <i>Fortify:</i> Four times per day, a stone wall can be created that is 12 inches thick, 10 feet high, and 30 feet long. This wall has a parapet and battlements across the top. (Alternatively, the power can be used to mend a broken existing wall. The gap to be filled can be no more than 300 square feet in area.) In addition, once per day, a great door of iron can be created that is set into one of the newly created walls. This door, 4 inches thick, may be a double door, a drawbridge, or a portcullis, as chosen by the wielder. <i>Siege Engine:</i> One heavy catapult, two light catapults, or three ballistae may be generated with each use of this power. The power can be used four times per day. Ammunition for 20 shots is included with each weapon created.</p><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, <i>inter-posing hand</i>,  <i>create food and water</i>,  <i>major creation</i>,  <i>wall of iron</i>,  <i>wall of stone; Market Price:</i> 465,665 gp; <i>Cost to Create:</i> 231,985 gp + 14,634 XP.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (89,'Invulnerability','Rod','Epic','No',NULL,'20','600,000 gp',NULL,'Craft Rod, Craft Epic Rod, iron body, resistance, spell resistance',NULL,NULL,'\n      <div topic=\"Invulnerability\" level=\"8\"><p><b>Invulnerability:</b> When held, this rod grants its wielder the following powers.</p><ul>\n <li> +5 enhancement bonus to natural armor.</li>\n <li> +5 resistance bonus on saving throws.</li>\n <li> Damage reduction 15/adamantine.</li>\n <li> Immunity to critical hits.</li>\n <li> Spell resistance 32.</li>\n</ul><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>iron body</i>,  <i>resistance</i>,  <i>spell resistance; Market Price:</i> 600,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (90,'Nightmares','Rod','Epic','No',NULL,'21','284,000 gp',NULL,'Craft Rod, Craft Epic Rod, nightmare, permanency, wail of the banshee',NULL,NULL,'\n      <div topic=\"Nightmares\" level=\"8\"><p><b>Nightmares:</b> Anyone who comes within 20 feet of the wielder of this rod feels a grave sense of unease. Each person so affected must make a Will save (DC 17) or suffer the effects of a <i>nightmare</i> spell the next time he or she falls asleep. The wielder is immune to this effect. Three times per day, the wielder can utter a command word that causes the rod to emit a horrid, inhuman scream. Up to twenty of the closest creatures within a 30-foot radius who hear this terrible wail believe that their worst nightmares have become reality and suffer the effects of a <i>wail of the banshee</i> spell (DC 23).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>nightmare</i>,  <i>permanency</i>,  <i>wail of the banshee; Market Price:</i> 284,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (91,'Paradise','Rod','Epic','No',NULL,'24','610,000 gp',NULL,'Craft Rod, Craft Epic Rod, Improved Heighten Spell, improved heightened gate',NULL,NULL,'\n      <div topic=\"Paradise\" level=\"8\"><p><b>Paradise:</b> This item creates a nondimensional space, similar in effect to a <i>rod of security</i>. However, the rod\'s possessor and up to 999 other creatures can stay in complete safety for up to 1,000 days divided by the number of creatures affected. Natural healing takes place at five times the normal pace. The rod functions like its nonepic counterpart in all other ways.</p><p><i>Caster Level:</i> 24th; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Improved Heighten Spell, improved heightened <i>gate; Market Price:</i> 610,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (92,'The Path','Rod','Epic','No',NULL,'21','306,870 gp',NULL,'Craft Rod, Craft Epic Rod, find the path, freedom of movement, pass without trace, wall of stone',NULL,NULL,'\n      <div topic=\"Path\" level=\"8\"><p><b>The Path:</b> This rod serves as an aid to trailblazing and travel. It grants the wielder a +30 enhancement bonus on Wilderness Lore checks for tracking and Intuit Direction checks. The handle of the rod is hollow, functioning like a telescope. When the wielder peers through it, the limits of vision are three times normal (and spotting distances for encounters are tripled). In addition, the telescoping handle enables the wielder to view things as though affected by a <i>true seeing</i> spell. The rod also has the following powers. <i>Map:</i> Three times per day a section of the rod unrolls like a scroll from a tube, revealing a map of the surrounding area, centered on the location of the rod. The area shown on the map covers an area as small as 50 feet in radius to as large as 24 miles in radius, zooming in or out with a set of command words. The map reveals natural topography and all types of structures (even hidden ones), but it will not show the location of creatures.</p><p><i>Passage:</i> Three times per day, this power allows the wielder and up to five others in a 20-foot radius to move unhindered through natural plant growth or bodies of water (as per the <i>freedom of movement</i> spell).</p><p><i>Bridge:</i> Once per day, this power allows the user to create a 5-foot-wide, 40-foot-long stone cause-way across chasms and canyons. The bridge created lasts for 1 hour.</p><p><i>Pass without Trace:</i> Once per day, this power can be used on the wielder and twenty others, for 21 minutes. It is otherwise as the spell of the same name (caster level 24th).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>find the path</i>,  <i>freedom of movement</i>,  <i>pass without trace</i>,  <i>wall of stone; Market Price:</i> 306,870 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (93,'Restless Death','Rod','Epic','No',NULL,'21','625,000 gp',NULL,'Craft Rod, Craft Epic Rod, animate dead, control undead, slay living',NULL,NULL,'\n      <div topic=\"Restless Death\" level=\"8\"><p><b>Restless Death:</b> The holder of this rod can rebuke or control undead as if he or she were four levels higher. (The rod doesn\'t grant the ability to rebuke or control undead if the holder doesn\'t already have it.) In addition, the wielder may speak a command word to cast <i>animate dead</i>. Any skeletons or zombies animated by the rod\'s power are automatically controlled by the rod, up to the rod\'s maximum limit of 42 HD, and they follow the orders of the rod\'s wielder. These undead don\'t count toward the wielder\'s limit of controlled undead. Finally, the wielder can speak a second command word to cast <i>slay living</i> (heightened to 10th level; DC 25).</p><p><i>Caster Level:</i> 21st; <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, <i>animate dead</i>,  <i>control undead</i>,  <i>slay living; Market Price:</i> 625,000 gp.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (94,'Wyrm, Brass','Rod','Epic','No',NULL,'34','1,458,200 gp',NULL,'Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Improved Heighten Spell, improved heightened polymorph, creator must be same alignment as dragon type','729,400 gp + 24,576 XP',NULL,'\n      <div topic=\"Wyrm\" level=\"8\"><p><b>Wyrm:</b> Any of the various rods in this series functions as a +<i>5 quarterstaff</i>. Upon casting the rod to the ground (a standard action) and uttering a command word, the rod grows into a specific type of dragon (depending on the specific type of rod) by the end of the round. The dragon created is a wyrm and obeys the commands of the owner. The dragon returns to rod form (a full-round action) whenever the wielder desires, or whenever it moves farther than 500 feet from the owner. If the dragon form is slain, it returns to rod form and cannot be activated again for three days. A <i>wyrm rod</i> only functions if the possessor is of the same alignment as the dragon type.</p><p><i>Caster Level:</i> 34th (white or brass), 35th (black or copper), 36th (green or bronze), 37th (blue or silver), 38th (red or gold); <i>Prerequisites:</i> Craft Rod, Craft Epic Rod, Craft Magic Arms and Armor, Craft Epic Magic Arms and Armor, Improved Heighten Spell, improved heightened <i>polymorph</i>,  creator must be same alignment as dragon type; <i>Market Price:</i> 1,458,200 gp (brass or white), 1,562,600 gp (black or copper), 1,670,600 gp (bronze or green), 1,782,200 gp (blue or silver), 1,897,400 gp (gold or red); <i>Cost to Create:</i> 729,400 gp + 24,576 XP (brass or white), 781,600 gp + 25,620 XP (black or copper), 835,600 gp + 26,700 XP (bronze or green), 891,400 gp + 27,816 XP (blue or silver), 949,000 gp + 28,968 XP (gold or red).</p><p/>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
